insert into public.categories(module,name,slug,parent_id,level,status,sort_order,icon_key,description) select module,name,slug,null,1,'active',sort_order,icon_key,description from category_main_sync on conflict(module,slug) where parent_id is null do update set name=excluded.name,status='active',sort_order=excluded.sort_order,icon_key=excluded.icon_key,description=excluded.description,updated_at=now();
insert into public.categories(module,name,slug,parent_id,level,status,sort_order,icon_key,description) select s.module,s.name,s.slug,p.id,2,'active',s.sort_order,s.icon_key,s.description from category_sub_sync s join public.categories p on p.module=s.module and p.level=1 and p.slug=s.parent_slug on conflict(module,slug,parent_id) where parent_id is not null do update set name=excluded.name,status='active',sort_order=excluded.sort_order,icon_key=excluded.icon_key,description=excluded.description,updated_at=now();
insert into public.categories(module,name,slug,parent_id,level,status,sort_order,icon_key,description) select s.module,s.name,s.slug,p.id,3,'active',s.sort_order,s.icon_key,s.description from category_l3_sync s join public.categories p on p.module=s.module and p.level=2 and p.slug=s.parent_slug on conflict(module,slug,parent_id) where parent_id is not null do update set name=excluded.name,status='active',sort_order=excluded.sort_order,icon_key=excluded.icon_key,description=excluded.description,updated_at=now();
